'use client';

import React from 'react';
import BottomSheet from './BottomSheet';
import { LucideIcon } from 'lucide-react';
import { useLanguage } from '../LanguageContext';

interface ComingSoonModalProps {
  isOpen: boolean;
  onClose: () => void;
  serviceName: string;
  Icon: LucideIcon;
}

export default function ComingSoonModal({ isOpen, onClose, serviceName, Icon }: ComingSoonModalProps) {
  const { t } = useLanguage();
  return (
    <BottomSheet isOpen={isOpen} onClose={onClose} title={serviceName}>
      <div className="flex flex-col items-center text-center p-6 space-y-4">
        <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center shadow-md text-white animate-pulse">
          <Icon className="w-8 h-8" />
        </div>
        <h2 className="text-xl font-black text-main">{serviceName}</h2>
        <div className="inline-flex items-center gap-1.5 bg-blue-500/10 text-blue-500 dark:text-blue-400 border border-blue-500/20 px-3 py-1 rounded-full text-xs font-black uppercase tracking-wider">
          {t('coming_soon') || 'Coming Soon'}
        </div>
        <p className="text-sm text-muted leading-relaxed max-w-sm">
          We are polishing this module to deliver a premium, production-grade superapp experience. Live APIs, route tracking, and bookings will be available in a future rollout. Thank you for your patience!
        </p>
        <button
          onClick={onClose}
          className="mt-4 px-6 py-2.5 bg-input hover:bg-input/80 text-main text-xs font-bold rounded-xl transition-all shadow-md active:scale-95 touch-manipulation border border-subtle"
        >
          {t('close') || 'Close'}
        </button>
      </div>
    </BottomSheet>
  );
}
