'use client';

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Train, ArrowRight, ShieldCheck, Ticket, ChevronUp, X, Sparkles } from 'lucide-react';

interface FloatingBookingDockProps {
  source: string;
  destination: string;
  bestSplit?: any;
  onOpenBoardingPass: () => void;
  onBookOfficial: () => void;
}

export function FloatingBookingDock({
  source,
  destination,
  bestSplit,
  onOpenBoardingPass,
  onBookOfficial,
}: FloatingBookingDockProps) {
  const [visible, setVisible] = useState(false);
  const [dismissed, setDismissed] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      if (dismissed) return;
      if (window.scrollY > 400) {
        setVisible(true);
      } else {
        setVisible(false);
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [dismissed]);

  if (!source || !destination || dismissed || !visible) return null;

  const hub = bestSplit?.hub || bestSplit?.via || '';
  const totalDuration = bestSplit?.total_duration || bestSplit?.duration || '';

  return (
    <AnimatePresence>
      <motion.aside
        aria-label="Quick booking actions"
        initial={{ y: 50, opacity: 0, scale: 0.95 }}
        animate={{ y: 0, opacity: 1, scale: 1 }}
        exit={{ y: 50, opacity: 0, scale: 0.95 }}
        transition={{ type: 'spring', damping: 24, stiffness: 280 }}
        className="fixed bottom-[calc(4.5rem+env(safe-area-inset-bottom,0px))] md:bottom-5 left-1/2 -translate-x-1/2 w-[calc(100%-1.5rem)] max-w-xl z-30 select-none"
      >
        <div className="bg-slate-900/90 dark:bg-[#0B132B]/95 backdrop-blur-xl border border-blue-500/30 text-white rounded-2xl p-2.5 sm:p-3 shadow-2xl shadow-blue-950/60 flex items-center justify-between gap-2.5">
          {/* Left: Route Summary */}
          <div className="flex items-center gap-2 min-w-0 pl-0.5 sm:pl-1 flex-1">
            <div className="w-7 h-7 sm:w-8 sm:h-8 rounded-xl bg-blue-500/20 border border-blue-500/30 flex items-center justify-center text-blue-400 shrink-0">
              <Train className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
            </div>
            <div className="min-w-0 flex-1">
              <div className="flex items-center gap-1 text-[11px] sm:text-xs font-black text-white truncate">
                <span className="truncate">{source}</span>
                <ArrowRight className="w-2.5 h-2.5 sm:w-3 sm:h-3 text-blue-400 shrink-0" />
                <span className="truncate">{destination}</span>
                {hub && (
                  <span className="hidden sm:inline-block text-[10px] text-blue-400 font-mono bg-blue-500/15 border border-blue-500/25 px-1.5 py-0.2 rounded-md truncate max-w-[80px]">
                    via {hub}
                  </span>
                )}
              </div>
              <p className="text-[9px] sm:text-[10px] text-emerald-400 font-bold flex items-center gap-1 leading-none mt-0.5 truncate">
                <ShieldCheck className="w-3 h-3 text-emerald-400 shrink-0" />
                <span className="truncate">Confirmed Seats</span>
                {totalDuration && <span className="text-slate-400 hidden sm:inline shrink-0">· {totalDuration}</span>}
              </p>
            </div>
          </div>

          {/* Right: Actions */}
          <div className="flex items-center gap-1 sm:gap-1.5 shrink-0">
            {/* Boarding Pass Trigger */}
            <button
              onClick={onOpenBoardingPass}
              aria-label="View Boarding Pass"
              title="View Digital Boarding Pass"
              className="p-1.5 sm:px-3 sm:py-2 rounded-xl bg-white/10 hover:bg-white/15 border border-white/10 text-white text-xs font-bold transition-all active:scale-95 flex items-center gap-1.5 cursor-pointer"
            >
              <Ticket className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-blue-400" />
              <span className="hidden sm:inline">Pass</span>
            </button>

            {/* Book Button */}
            <button
              onClick={onBookOfficial}
              className="px-2.5 sm:px-4 py-1.5 sm:py-2 rounded-xl bg-blue-600 hover:bg-blue-500 text-white text-xs font-black transition-all shadow-md shadow-blue-600/30 active:scale-95 flex items-center gap-1.5 cursor-pointer whitespace-nowrap"
            >
              <Sparkles className="w-3 h-3 sm:w-3.5 sm:h-3.5 text-amber-300" />
              <span className="sm:inline hidden">Book Seats</span>
              <span className="sm:hidden inline">Book</span>
            </button>

            {/* Dismiss */}
            <button
              onClick={() => setDismissed(true)}
              aria-label="Dismiss bottom bar"
              className="p-1 rounded-lg text-slate-400 hover:text-white transition-colors cursor-pointer"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      </motion.aside>
    </AnimatePresence>
  );
}

export default FloatingBookingDock;
