'use client';

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Train, Layers, Info, CheckCircle2, Search } from 'lucide-react';
import axios from 'axios';
import { API_BASE } from '../../lib/api';
import { SeatMap } from '../SeatMap';
import { CoachVisualizer, FormattedCoach } from './CoachVisualizer';
import { formatStationWithCode } from '../../utils/stationNames';

interface CoachSeatMapModalProps {
  trainNo: string;
  trainName: string;
  fromStn?: string;
  toStn?: string;
  initialClass?: string;
  onClose: () => void;
}

// Module-level in-memory cache: cleanTrainNo -> { coaches, totalCoaches }
const coachCompositionCache = new Map<string, { coaches: FormattedCoach[]; totalCoaches: number }>();

export function CoachSeatMapModal({
  trainNo,
  trainName,
  fromStn,
  toStn,
  initialClass = 'SL',
  onClose,
}: CoachSeatMapModalProps) {
  const cleanNo = String(trainNo).replace(/\D/g, '').padStart(5, '0');
  const cachedInitial = coachCompositionCache.get(cleanNo);

  const [mounted, setMounted] = useState(false);
  const [activeTab, setActiveTab] = useState<'coaches' | 'seats'>('coaches');
  const [coaches, setCoaches] = useState<FormattedCoach[]>(cachedInitial?.coaches || []);
  const [loading, setLoading] = useState(!cachedInitial);
  const [error, setError] = useState(false);
  const [totalCoaches, setTotalCoaches] = useState(cachedInitial?.totalCoaches || 0);
  const [selectedCoachType, setSelectedCoachType] = useState<string>(initialClass);

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    // If already in client cache, skip network request entirely
    const cached = coachCompositionCache.get(cleanNo);
    if (cached && cached.coaches && cached.coaches.length > 0) {
      setCoaches(cached.coaches);
      setTotalCoaches(cached.totalCoaches);
      setLoading(false);
      return;
    }

    let isMounted = true;
    const fetchCoaches = async () => {
      setLoading(true);
      setError(false);
      try {
        const res = await axios.get(`${API_BASE}/trains/coaches/${cleanNo}`, { timeout: 10000 });
        const cData = res.data?.data;
        if (cData && Array.isArray(cData.coaches) && cData.coaches.length > 0) {
          coachCompositionCache.set(cleanNo, {
            coaches: cData.coaches,
            totalCoaches: cData.total_coaches || cData.coaches.length,
          });
          if (isMounted) {
            setCoaches(cData.coaches);
            setTotalCoaches(cData.total_coaches || cData.coaches.length);
          }
        } else {
          if (isMounted) setError(true);
        }
      } catch (err) {
        if (isMounted) setError(true);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchCoaches();
    return () => {
      isMounted = false;
    };
  }, [cleanNo]);

  if (!mounted) return null;

  return createPortal(
    <AnimatePresence>
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-3 sm:p-4 bg-black/75 backdrop-blur-md overflow-y-auto">
        <motion.div
          initial={{ opacity: 0, scale: 0.95, y: 15 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: 15 }}
          transition={{ type: 'spring', damping: 25, stiffness: 300 }}
          className="relative w-full max-w-2xl bg-card border border-subtle dark:border-white/10 rounded-3xl p-5 sm:p-6 shadow-2xl overflow-hidden my-auto"
        >
          {/* Close button */}
          <button
            onClick={onClose}
            aria-label="Close coach modal"
            className="absolute top-4 right-4 w-8 h-8 rounded-full bg-subtle hover:bg-card border border-strong text-muted hover:text-main flex items-center justify-center transition-all cursor-pointer z-10"
          >
            <X className="w-4 h-4" />
          </button>

          {/* Modal Header */}
          <div className="flex items-center gap-3 mb-5 pr-8">
            <div className="w-10 h-10 rounded-2xl bg-blue-500/10 border border-blue-500/20 text-blue-600 dark:text-blue-400 flex items-center justify-center shrink-0">
              <Train className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2 flex-wrap">
                <span className="font-mono text-xs font-black text-blue-600 dark:text-blue-400">
                  #{cleanNo}
                </span>
                <h3 className="text-base sm:text-lg font-black text-main truncate">
                  {trainName}
                </h3>
              </div>
              {fromStn && toStn && (
                <p className="text-xs text-muted font-medium">
                  {formatStationWithCode(fromStn)} ➔ {formatStationWithCode(toStn)}
                </p>
              )}
            </div>
          </div>

          {/* Segmented Tab Switcher */}
          <div className="flex p-1 bg-subtle/80 border border-strong rounded-2xl mb-5">
            <button
              onClick={() => setActiveTab('coaches')}
              className={`flex-1 py-2.5 px-3 rounded-xl text-xs font-black transition-all flex items-center justify-center gap-2 cursor-pointer ${
                activeTab === 'coaches'
                  ? 'bg-card text-main shadow-sm border border-subtle dark:border-white/10'
                  : 'text-muted hover:text-main'
              }`}
            >
              <Train className="w-4 h-4 text-blue-500" />
              <span>Coach Position Rake</span>
            </button>

            <button
              onClick={() => setActiveTab('seats')}
              className={`flex-1 py-2.5 px-3 rounded-xl text-xs font-black transition-all flex items-center justify-center gap-2 cursor-pointer ${
                activeTab === 'seats'
                  ? 'bg-card text-main shadow-sm border border-subtle dark:border-white/10'
                  : 'text-muted hover:text-main'
              }`}
            >
              <Layers className="w-4 h-4 text-indigo-500" />
              <span>Berth Seat Layout</span>
            </button>
          </div>

          {/* ── TAB 1: COACH POSITION RAKE ── */}
          {activeTab === 'coaches' && (
            <div>
              {loading ? (
                <div className="py-12 flex flex-col items-center justify-center gap-3">
                  <div className="w-8 h-8 border-3 border-blue-500 border-t-transparent rounded-full animate-spin" />
                  <p className="text-xs text-muted font-medium">Loading authoritative coach sequence...</p>
                </div>
              ) : error || coaches.length === 0 ? (
                <div className="py-10 px-4 text-center bg-subtle/40 border border-strong rounded-2xl">
                  <p className="text-sm font-bold text-main mb-1">Standard Coach Composition</p>
                  <p className="text-xs text-muted mb-4">
                    Engine ➔ SLR ➔ GS ➔ S1-S8 (Sleeper) ➔ B1-B6 (3AC) ➔ A1-A2 (2AC) ➔ SLR
                  </p>
                  <button
                    onClick={() => setActiveTab('seats')}
                    className="inline-flex items-center gap-1.5 px-4 py-2 rounded-xl bg-blue-600 text-white text-xs font-bold"
                  >
                    View Berth Layout Map
                  </button>
                </div>
              ) : (
                <CoachVisualizer
                  coaches={coaches}
                  totalCoaches={totalCoaches}
                  trainNo={cleanNo}
                  trainName={trainName}
                />
              )}
            </div>
          )}

          {/* ── TAB 2: INTERACTIVE BERTH SEAT MAP ── */}
          {activeTab === 'seats' && (
            <div className="space-y-4">
              <SeatMap initialCoachType={selectedCoachType} />
            </div>
          )}
        </motion.div>
      </div>
    </AnimatePresence>,
    document.body
  );
}

export default CoachSeatMapModal;
