'use client';

import React, { useState, useEffect } from 'react';
import { Award, Clock, ArrowRight, GitFork, Sparkles, ShieldCheck, CheckCircle2, Volume2, Square } from 'lucide-react';
import { clsx } from 'clsx';
import { voiceService } from '@/lib/voiceService';
import { useLanguage } from '../LanguageContext';
import { getStationDetails } from '@/utils/stationNames';

interface SplitJourneySummaryCardProps {
  splitResults: any[];
  onJumpToBestRoute?: () => void;
}

export function SplitJourneySummaryCard({
  splitResults,
  onJumpToBestRoute,
}: SplitJourneySummaryCardProps) {
  const { language, setLanguage } = useLanguage();
  const [isVoicePlaying, setIsVoicePlaying] = useState(false);
  const [splitVoiceLang, setSplitVoiceLang] = useState<'hi' | 'en'>(() => {
    if (typeof window !== 'undefined') {
      const saved = voiceService.getLanguage();
      if (saved === 'en') return 'en';
    }
    return 'hi';
  });

  useEffect(() => {
    const handleSync = (e: any) => {
      const l = e.detail?.lang;
      if (l === 'hi' || l === 'en') {
        setSplitVoiceLang(l);
      }
    };
    window.addEventListener('trayago:language-change', handleSync);
    return () => window.removeEventListener('trayago:language-change', handleSync);
  }, []);

  // Stop speech playback on component unmount
  useEffect(() => {
    return () => {
      voiceService.stop();
    };
  }, []);

  // Reset voice playback state when split results change
  useEffect(() => {
    if (isVoicePlaying) {
      voiceService.stop();
      setIsVoicePlaying(false);
    }
  }, [splitResults]);

  if (!splitResults || splitResults.length === 0) return null;

  // 1. Determine best recommended split route (fastest duration)
  const sorted = [...splitResults].sort((a, b) => {
    const getDurMinutes = (s: any) => {
      const durationStr = s.total_duration || s.duration || '';
      const matches = durationStr.match(/(\d+)h\s*(\d+)m/);
      if (matches) {
        return parseInt(matches[1], 10) * 60 + parseInt(matches[2], 10);
      }
      return 9999;
    };
    return getDurMinutes(a) - getDurMinutes(b);
  });

  const bestRoute = sorted[0];
  const isSameTrain = bestRoute?.isSameTrain === true || bestRoute?.rescueType === 'SAME_TRAIN_SEGMENT' ||
    (bestRoute?.legs?.[0] && bestRoute?.legs?.[1] && (bestRoute.legs[0].trainNo || bestRoute.legs[0].number) === (bestRoute.legs[1].trainNo || bestRoute.legs[1].number));
  const rawBestHub = bestRoute?.hub || bestRoute?.via || bestRoute?.transfer_station || '';
  const bestHubDetails = getStationDetails(rawBestHub, bestRoute?.hubName || bestRoute?.hub_name);
  const bestHubName = bestHubDetails.name || 'Intermediate Junction';
  const bestHubCode = bestHubDetails.code;
  const bestHubFormatted = bestHubDetails.full;
  const bestHubHeading = bestHubName.toLowerCase().includes('junction') || bestHubName.toLowerCase().includes('jn')
    ? bestHubName
    : `${bestHubName} Junction`;

  const bestDuration = bestRoute?.total_duration || bestRoute?.duration || 'Optimal Time';
  const bestBuffer = Number(bestRoute?.wait_time ?? bestRoute?.bufferMinutes ?? 0);
  const bestBufferStr = bestBuffer > 0 ? `${Math.floor(bestBuffer / 60)}h ${bestBuffer % 60}m` : '1h 45m';

  // Calculate shortest buffer among all results
  const allBuffers = splitResults.map((s) => Number(s.wait_time ?? s.bufferMinutes ?? 0)).filter((b) => b > 0);
  const shortestBuffer = allBuffers.length > 0 ? Math.min(...allBuffers) : bestBuffer;
  const shortestBufferStr = shortestBuffer > 0 ? `${Math.floor(shortestBuffer / 60)}h ${shortestBuffer % 60}m` : bestBufferStr;

  const handleSelectSplitVoiceLang = (newLang: 'hi' | 'en') => {
    setSplitVoiceLang(newLang);
    voiceService.setLanguage(newLang);
    try {
      setLanguage(newLang);
    } catch {}

    const wasPlaying = isVoicePlaying;
    voiceService.stop();
    setIsVoicePlaying(false);

    if (wasPlaying) {
      setTimeout(() => {
        playSplitVoice(newLang);
      }, 250);
    }
  };

  const playSplitVoice = (langToUse: 'hi' | 'en') => {
    const originStn =
      bestRoute?.source ||
      bestRoute?.from ||
      bestRoute?.origin ||
      bestRoute?.legs?.[0]?.from ||
      '';
    const destStn =
      bestRoute?.destination ||
      bestRoute?.to ||
      bestRoute?.legs?.[bestRoute?.legs?.length - 1]?.to ||
      '';

    setIsVoicePlaying(true);
    voiceService.speakSplitJourneySummary(
      {
        origin: originStn,
        destination: destStn,
        hub: bestHubName !== 'Intermediate Junction' ? bestHubName : undefined,
        totalDuration: bestDuration !== 'Optimal Time' ? bestDuration : undefined,
        bufferMinutes: bestBuffer > 0 ? bestBuffer : undefined,
        bufferFormatted: bestBufferStr,
        totalOptions: splitResults.length,
        hasConfirmedQuota: true,
      },
      langToUse,
      'female',
      () => {
        setIsVoicePlaying(false);
      }
    );
  };

  const handleToggleVoice = () => {
    if (isVoicePlaying) {
      voiceService.stop();
      setIsVoicePlaying(false);
      return;
    }
    playSplitVoice(splitVoiceLang);
  };

  return (
    <div className="w-full bg-card border border-slate-200/90 dark:border-slate-800 rounded-3xl p-5 sm:p-7 shadow-sm relative overflow-hidden mb-6">
      {/* Subtle background ambient flare */}
      <div className="absolute -top-24 -right-24 w-60 h-60 bg-blue-500/10 dark:bg-blue-500/15 rounded-full blur-3xl pointer-events-none" />

      {/* Header bar: Executive context tag */}
      <div className="flex flex-wrap items-center justify-between gap-2 mb-5">
        <div className="flex items-center gap-2">
          <div className="p-1.5 bg-blue-500/10 rounded-lg text-blue-600 dark:text-blue-400">
            <Sparkles className="w-4 h-4" />
          </div>
          <span className="text-xs font-bold uppercase tracking-wider text-muted">
            Executive Route Intelligence
          </span>
        </div>
        <span className="text-xs font-semibold px-2.5 py-0.5 bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 rounded-full border border-emerald-500/20 flex items-center gap-1">
          <CheckCircle2 className="w-3 h-3" /> Feasible Alternatives Verified
        </span>
      </div>

      {/* Main Hierarchy Grid: 1 Hero Tile (Big) + 3 Secondary Compact Tiles */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
        
        {/* ── HERO TILE (7 Cols on desktop): High visual prominence ── */}
        <div className={clsx(
          "lg:col-span-7 border rounded-2xl p-5 sm:p-6 relative flex flex-col justify-between",
          isSameTrain
            ? "bg-gradient-to-br from-emerald-500/15 via-emerald-500/5 to-transparent border-emerald-500/30"
            : "bg-gradient-to-br from-blue-500/10 via-indigo-500/5 to-transparent border-blue-500/25"
        )}>
          <div>
            <div className={clsx(
              "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-black uppercase tracking-wider mb-3",
              isSameTrain
                ? "bg-emerald-500/15 text-emerald-700 dark:text-emerald-300"
                : "bg-blue-500/15 text-blue-600 dark:text-blue-300"
            )}>
              <Award className={clsx("w-3.5 h-3.5", isSameTrain ? "text-emerald-500" : "text-blue-500")} />
              {isSameTrain ? "Top Recommended Same-Train Rescue" : "Top Recommended Connection"}
            </div>

            <h3 className="text-xl sm:text-2xl font-extrabold text-main mb-2 flex items-center gap-2 flex-wrap">
              <span>{isSameTrain ? "Seat Switch at " : "Via "}<span className={isSameTrain ? "text-emerald-600 dark:text-emerald-400" : "text-blue-600 dark:text-blue-400"}>{bestHubHeading}</span></span>
              {bestHubCode && (
                <span className={clsx(
                  "text-xs sm:text-sm font-mono font-bold px-2 py-0.5 rounded-lg border",
                  isSameTrain
                    ? "bg-emerald-500/10 border-emerald-500/20 text-emerald-600 dark:text-emerald-400"
                    : "bg-blue-500/10 border-blue-500/20 text-blue-500 dark:text-blue-400"
                )}>
                  ({bestHubCode})
                </span>
              )}
            </h3>

            <p className="text-xs sm:text-sm text-secondary leading-relaxed mb-4">
              {isSameTrain
                ? <>Fastest route found ({bestDuration}) with <strong>zero train change</strong>! Stay on board and switch seats at <strong className="text-main">{bestHubFormatted}</strong>. Unlocks confirmed tickets on this train.</>
                : <>Fastest route found ({bestDuration}) with a safe transfer buffer of {bestBufferStr} at <strong className="text-main">{bestHubFormatted}</strong>. Unlocks confirmed intermediate booking quotas.</>}
            </p>
          </div>

          <div className="flex flex-wrap items-center justify-between gap-3 pt-4 border-t border-blue-500/20">
            <div className="flex items-center gap-2">
              <span className="text-xs text-muted">Total Journey:</span>
              <span className="text-sm font-black text-main font-mono tabular-nums">{bestDuration}</span>
            </div>

            <div className="flex items-center gap-2 flex-wrap">
              {/* Language Selector */}
              <div className="flex items-center gap-0.5 bg-input/80 p-0.5 rounded-lg border border-subtle text-[9px]">
                <button
                  type="button"
                  onClick={() => handleSelectSplitVoiceLang('hi')}
                  className={clsx(
                    "px-1.5 py-0.5 rounded-md font-bold transition-all cursor-pointer",
                    splitVoiceLang === 'hi'
                      ? "bg-indigo-600 text-white font-black shadow-xs"
                      : "text-muted hover:text-main"
                  )}
                >
                  🇮🇳 हिंदी
                </button>
                <button
                  type="button"
                  onClick={() => handleSelectSplitVoiceLang('en')}
                  className={clsx(
                    "px-1.5 py-0.5 rounded-md font-bold transition-all cursor-pointer",
                    splitVoiceLang === 'en'
                      ? "bg-indigo-600 text-white font-black shadow-xs"
                      : "text-muted hover:text-main"
                  )}
                >
                  🌐 English
                </button>
              </div>

              {/* User-Triggered Listen Route Control */}
              <button
                type="button"
                onClick={handleToggleVoice}
                aria-label={isVoicePlaying ? "Stop split journey voice announcement" : "Listen to split route summary"}
                aria-pressed={isVoicePlaying}
                className={clsx(
                  "min-h-[44px] min-w-[44px] px-3.5 py-2 rounded-xl text-xs font-bold transition-all border flex items-center gap-2 cursor-pointer active:scale-95 touch-manipulation focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500",
                  isVoicePlaying
                    ? "bg-indigo-600 text-white border-indigo-400 animate-pulse shadow-md font-black"
                    : "bg-indigo-500/15 hover:bg-indigo-500/25 text-indigo-600 dark:text-indigo-400 border-indigo-500/30 hover:border-indigo-500/50"
                )}
              >
                {isVoicePlaying ? (
                  <>
                    <Square size={13} className="fill-current text-white" />
                    <span>{splitVoiceLang === 'hi' ? 'रुकिए' : 'Stop'}</span>
                  </>
                ) : (
                  <>
                    <Volume2 size={14} />
                    <span>{splitVoiceLang === 'hi' ? 'रूट सुनें' : 'Listen Route'}</span>
                  </>
                )}
              </button>

              {onJumpToBestRoute && (
                <button
                  type="button"
                  onClick={onJumpToBestRoute}
                  className="min-h-[44px] px-4 py-2 bg-blue-600 hover:bg-blue-700 active:scale-95 text-white text-xs font-bold rounded-xl transition-all shadow-sm flex items-center gap-1.5 cursor-pointer touch-manipulation"
                >
                  <span>View Route Details</span>
                  <ArrowRight className="w-3.5 h-3.5" />
                </button>
              )}
            </div>
          </div>
        </div>

        {/* ── 3 SECONDARY METRIC TILES (5 Cols on desktop): Compact visual balance ── */}
        <div className="lg:col-span-5 grid grid-cols-1 sm:grid-cols-3 lg:grid-cols-1 gap-3">
          
          {/* Secondary 1: Total Combinations */}
          <div className="p-4 bg-input/60 dark:bg-surface/60 border border-subtle rounded-2xl flex items-center gap-3.5">
            <div className="p-2.5 bg-blue-500/10 text-blue-600 dark:text-blue-400 rounded-xl shrink-0">
              <GitFork className="w-5 h-5" />
            </div>
            <div className="min-w-0">
              <p className="text-[11px] font-semibold text-muted uppercase tracking-wider truncate">
                Discovered Routes
              </p>
              <p className="text-base font-extrabold text-main mt-0.5 tabular-nums">
                {splitResults.length} Feasible Options
              </p>
            </div>
          </div>

          {/* Secondary 2: Shortest Layover Buffer */}
          <div className="p-4 bg-input/60 dark:bg-surface/60 border border-subtle rounded-2xl flex items-center gap-3.5">
            <div className="p-2.5 bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 rounded-xl shrink-0">
              <Clock className="w-5 h-5" />
            </div>
            <div className="min-w-0">
              <p className="text-[11px] font-semibold text-muted uppercase tracking-wider truncate">
                Shortest Safe Transfer
              </p>
              <p className="text-base font-extrabold text-main mt-0.5 tabular-nums">
                {shortestBufferStr}
              </p>
            </div>
          </div>

          {/* Secondary 3: Quota Advantage */}
          <div className="p-4 bg-input/60 dark:bg-surface/60 border border-subtle rounded-2xl flex items-center gap-3.5">
            <div className="p-2.5 bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 rounded-xl shrink-0">
              <ShieldCheck className="w-5 h-5" />
            </div>
            <div className="min-w-0">
              <p className="text-[11px] font-semibold text-muted uppercase tracking-wider truncate">
                Waitlist Protection
              </p>
              <p className="text-base font-extrabold text-main mt-0.5">
                Dual-Leg Independent Quota
              </p>
            </div>
          </div>

        </div>

      </div>
    </div>
  );
}
