"use client";

import React from "react";
import clsx from "clsx";
import { ShieldCheck } from "lucide-react";

interface LiveTelemetryBadgeProps {
  className?: string;
  compact?: boolean;
}

/**
 * LiveTelemetryBadge (Reel 4 Concept)
 * Displays an active radar pulse and verification badge indicating real-time
 * synchronization with upstream Indian Railways feeds.
 */
export function LiveTelemetryBadge({ className, compact = false }: LiveTelemetryBadgeProps) {
  return (
    <div
      className={clsx(
        "inline-flex items-center gap-1.5 text-[10px] font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 border border-emerald-500/25 rounded-xl shadow-xs select-none transition-all duration-200",
        compact ? "px-2 py-1 min-h-[28px]" : "px-2.5 py-1.5 min-h-[36px]",
        className
      )}
      title="Real-time availability synced with official Indian Railways feeds. Direct booking redirects to IRCTC."
    >
      {/* Animated Radar Pulse Dot */}
      <span className="relative flex h-2 w-2 shrink-0 items-center justify-center">
        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75" />
        <span className="relative inline-flex rounded-full h-1.5 w-1.5 bg-emerald-500" />
      </span>

      <span className="tracking-wide">Live Telemetry</span>
      {!compact && (
        <>
          <span className="text-emerald-500/40" aria-hidden="true">•</span>
          <span className="text-[9px] font-semibold text-emerald-500/80 uppercase tracking-wider flex items-center gap-0.5">
            <ShieldCheck className="w-2.5 h-2.5 shrink-0" />
            IRCTC Verified
          </span>
        </>
      )}
    </div>
  );
}

export default LiveTelemetryBadge;
